  { let $v := string($addr/createdBy)
    return if ($v != '') then <createdBy>{$v}</createdBy> else () }

{
  let $epoch-ms := data($addr/createDate)
  return
    if (exists($addr/createDate))
    then
      <createdDate>
        {
          date:addToDate(
            xs:dateTime('1970-01-01T00:00:00'),
            'SS',
            xs:integer(floor($epoch-ms div 1000))
          )
        }
      </createdDate>
